def check_days(day1, day2):
    days = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
    index1 = days.index(day1)
    index2 = days.index(day2)

    return abs(index1 - index2) == 1 or (index1 == 6 and index2 == 0)

# Example usage:
day1 = input().strip()
day2 = input().strip()

if check_days(day1, day2):
    print("YES")
else:
    print("NO")
